    private void cancelSearches(){for(Future<?> f:searchRequests)f.cancel(true);searchRequests.clear();searchIo.purge();}
    private static final class SearchBatch { final LinkedHashMap<String,Track> tracks=new LinkedHashMap<>();final List<String> errors=new ArrayList<>();int pending; }
    private void doSearch(FrameLayout results,String q){cancelSearches();int token=++generation;if(q.length()<2){searchEmpty(results,"Escribí al menos dos letras para buscar.");return;}if(q.length()>160){searchEmpty(results,"Usá un nombre de hasta 160 caracteres.");return;}
        if(!searchKind.equals("tracks")){results.removeAllViews();TextView loading=text(this,"Buscando en Audius…",14,MUTED,false);pad(loading,24,24);results.addView(loading);boolean artists=searchKind.equals("artists");searchRequests.add(searchIo.submit(()->{try{List<AudiusProvider.Collection> found=new AudiusProvider().collections(q,artists);runOnUiThread(()->{if(token==generation)showCollections(results,found);});}catch(Exception e){runOnUiThread(()->{if(token==generation)searchEmpty(results,"No se pudo consultar Audius. En Canciones también buscás en YouTube.");});}}));return;}
        SearchBatch batch=new SearchBatch();String lower=q.toLowerCase(Locale.ROOT);for(Track t:store.offline())if((t.title+" "+t.artist).toLowerCase(Locale.ROOT).contains(lower))batch.tracks.put(t.key(),t);
        List<MusicProvider> providers=new ArrayList<>();providers.add(new YouTubeProvider(getSharedPreferences("settings",MODE_PRIVATE).getString("youtubeBridge","")));providers.add(new AudiusProvider());
        String client=getSharedPreferences("settings",MODE_PRIVATE).getString("jamendo","");if(!client.isEmpty())providers.add(new JamendoProvider(client));String bridge=getSharedPreferences("settings",MODE_PRIVATE).getString("spotifyBridge","");if(!bridge.isEmpty())providers.add(new SpotifyMetadataProvider(bridge));batch.pending=providers.size();showSearchResults(results,q,batch);
        for(MusicProvider provider:providers)searchRequests.add(searchIo.submit(()->{List<Track> found=new ArrayList<>();String warning="";try{found=provider.search(q);for(Track t:found)store.save(mergeLocal(t));if(provider instanceof YouTubeProvider)store.cache("youtube:"+q.toLowerCase(Locale.ROOT),Track.encode(found));}catch(Exception e){warning=provider.name()+" no respondió";if(provider instanceof YouTubeProvider){found=Track.decode(store.cached("youtube:"+q.toLowerCase(Locale.ROOT)));if(!found.isEmpty())warning="YouTube: últimos resultados guardados";}}
            List<Track> received=found;String note=warning;runOnUiThread(()->{if(destroyed||token!=generation)return;for(Track t:received)batch.tracks.putIfAbsent(t.key(),t);if(!note.isEmpty())batch.errors.add(note);batch.pending--;showSearchResults(results,q,batch);});}));
    }
    private void showSearchResults(FrameLayout results,String q,SearchBatch batch){
        List<Track> tracks=new ArrayList<>(batch.tracks.values());tracks.sort(Comparator.comparingInt(t->!t.local.isEmpty()?0:t.youtube()?1:2));results.removeAllViews();LinearLayout h=section();String count=tracks.size()+" resultados"+(batch.pending>0?" · buscando en "+batch.pending+" fuentes…":"");add(h,text(this,count,12,MUTED,false));
        if(!batch.errors.isEmpty()){gap(h,8);add(h,text(this,String.join(" · ",batch.errors),12,MUTED,false));gap(h,12);add(h,button(this,"Reintentar búsqueda",()->doSearch(results,q)));}
        if(batch.pending==0&&tracks.isEmpty()){gap(h,12);add(h,button(this,"Abrir búsqueda en YouTube",()->openWeb("https://www.youtube.com/results?search_query="+Net.enc(q))));}
        RecyclerView rv=new RecyclerView(this);rv.setLayoutManager(new LinearLayoutManager(this));rv.setAdapter(new TrackAdapter(h,tracks,batch.pending>0?"Buscando canciones…":"No encontramos resultados. Probá otro nombre o abrí la búsqueda en YouTube.",-1));results.addView(rv);visible=tracks;
    }
    private void showCollections(FrameLayout results,List<AudiusProvider.Collection> found){results.removeAllViews();LinearLayout b=section();add(b,text(this,found.size()+" resultados en Audius",12,MUTED,false));gap(b,12);for(AudiusProvider.Collection c:found){LinearLayout r=row(this);pad(r,0,10);Track fake=new Track();fake.title=c.name;fake.id=c.id;fake.artwork=c.art;r.addView(cover(this,fake,56));LinearLayout words=col(this);pad(words,14,0);add(words,heading(c.name,16));gap(words,6);add(words,text(this,c.by,12,MUTED,false));r.addView(words,new LinearLayout.LayoutParams(0,-2,1));r.setOnClickListener(v->loadCollection(c));add(b,r);}if(found.isEmpty())add(b,text(this,"Sin resultados para esta búsqueda.",14,MUTED,false));ScrollView s=new ScrollView(this);s.addView(b);results.addView(s);}
    private void loadCollection(AudiusProvider.Collection c){page="collection";int token=++generation;renderNav();LinearLayout h=section();add(h,button(this,"← Volver a buscar",()->navigate("search")));gap(h,20);add(h,heading(c.name,28));gap(h,8);add(h,text(this,c.by+" · Audius",13,MUTED,false));TextView retry=button(this,"Reintentar colección",()->loadCollection(c));retry.setVisibility(View.GONE);add(h,retry);renderTracks(h,new ArrayList<>(),"Cargando canciones…",-1);io.execute(()->{try{List<Track> tracks=new AudiusProvider().collection(c);for(Track t:tracks)store.save(mergeLocal(t));runOnUiThread(()->{if(token==generation)renderTracks(h,tracks,"No hay canciones públicas disponibles.",-1);});}catch(Exception e){runOnUiThread(()->{if(token==generation){retry.setVisibility(View.VISIBLE);renderTracks(h,new ArrayList<>(),"No se pudo cargar la colección. Volvé a intentarlo.",-1);}});}});}
