    private void providerSettings(){LinearLayout b=section();add(b,text(this,"YouTube y Audius funcionan sin configuración. El audio se resuelve con NewPipeExtractor dentro de Open Music, sin configurar un servidor. Jamendo requiere tu propio client_id. El puente opcional de Spotify busca metadatos; el audio se resuelve en fuentes autorizadas.",14,MUTED,false));gap(b,18);add(b,heading("Jamendo client_id",16));EditText jam=new EditText(this);jam.setSingleLine();jam.setText(getSharedPreferences("settings",MODE_PRIVATE).getString("jamendo",""));jam.setTextColor(TEXT);jam.setHint("Opcional");add(b,jam);gap(b,18);add(b,heading("Puente Spotify (HTTPS)",16));EditText spotify=new EditText(this);spotify.setSingleLine();spotify.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);spotify.setTextColor(TEXT);spotify.setHint("https://tu-servidor");spotify.setText(getSharedPreferences("settings",MODE_PRIVATE).getString("spotifyBridge",""));add(b,spotify);gap(b,18);add(b,heading("Puente yt-search (HTTPS, opcional)",16));EditText youtube=new EditText(this);youtube.setSingleLine();youtube.setTextColor(TEXT);youtube.setHint("https://tu-servidor");youtube.setText(getSharedPreferences("settings",MODE_PRIVATE).getString("youtubeBridge",""));add(b,youtube);ScrollView providersScroll=new ScrollView(this);providersScroll.addView(b);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Proveedores de música").setView(providersScroll).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",null).create();dialog.setOnShowListener(x->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String url=spotify.getText().toString().trim().replaceAll("/+$","");if(!url.isEmpty()&&(!url.startsWith("https://")||Uri.parse(url).getHost()==null||Uri.parse(url).getUserInfo()!=null)){spotify.setError("Ingresá una dirección HTTPS válida");return;}String youtubeUrl=youtube.getText().toString().trim().replaceAll("/+$","");if(!youtubeUrl.isEmpty()&&(!youtubeUrl.startsWith("https://")||Uri.parse(youtubeUrl).getHost()==null||Uri.parse(youtubeUrl).getUserInfo()!=null)){youtube.setError("Ingresá una dirección HTTPS válida");return;}getSharedPreferences("settings",MODE_PRIVATE).edit().putString("youtubeBridge",youtubeUrl).putString("jamendo",jam.getText().toString().trim()).putString("spotifyBridge",url).apply();toast("Proveedores guardados");dialog.dismiss();}));dialog.show();}
