    private void handleBackup(int code,Uri uri){toast(code==102?"Preparando respaldo…":"Validando respaldo…");io.execute(()->{try{if(code==102){String text=LibraryBackup.export(store);try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("No se pudo abrir el archivo");out.write(text.getBytes(StandardCharsets.UTF_8));}runOnUiThread(()->toast("Respaldo guardado: playlists y favoritos, sin archivos de audio."));}else{int count;try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Archivo vacío");count=LibraryBackup.restore(store,new String(readBounded(in,10*1024*1024),StandardCharsets.UTF_8));}final int restored=count;runOnUiThread(()->{toast(restored+" entradas restauradas; tu biblioteca anterior se conserva.");navigate("library");});}}catch(Exception e){runOnUiThread(()->toast("No se pudo "+(code==102?"exportar":"restaurar")+": "+e.getMessage()));}});}
    @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);com.google.zxing.integration.android.IntentResult scan=com.google.zxing.integration.android.IntentIntegrator.parseActivityResult(code,result,data);if(scan!=null){if(scan.getContents()!=null)social.open(scan.getContents());return;}if(result!=RESULT_OK||data==null)return;
        if((code==108||code==109)&&data.getData()!=null){Uri image=data.getData();toast("Preparando imagen…");io.execute(()->{try{String path=ProfileImages.copy(this,image,code==109);social.profile.image(code==109,path);runOnUiThread(()->{if(!destroyed){navigate("profile");toast("Imagen guardada");}});}catch(Exception e){runOnUiThread(()->toast("No se pudo guardar la imagen: "+e.getMessage()));}});return;}
        if(code==105&&data.getData()!=null){savePlaylistCover(data.getData());return;}
        if((code==106||code==107)&&data.getData()!=null){handleProfileFile(code,data.getData());return;}if((code==102||code==103)&&data.getData()!=null){handleBackup(code,data.getData());return;}if(code==104&&data.getData()!=null){Uri uri=data.getData();io.execute(()->{try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Archivo vacío");List<Track> tracks=YoutubeDlImport.parse(new String(readBounded(in,10*1024*1024),StandardCharsets.UTF_8));long id=store.createPlaylist("Importada de youtube-dl");for(Track t:tracks)store.add(id,t);runOnUiThread(()->{toast(tracks.size()+" videos importados");navigate("library");});}catch(Exception e){runOnUiThread(()->toast("No se pudo importar youtube-dl: "+e.getMessage()));}});return;}if(code==100){List<Uri> uris=new ArrayList<>();if(data.getClipData()!=null)for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());else if(data.getData()!=null)uris.add(data.getData());toast("Importando "+uris.size()+" archivos…");for(Uri uri:uris)try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}io.execute(()->{int count=0;for(Uri uri:uris)try{Track t=localTrack(uri);store.save(t);count++;}catch(Exception ignored){}int imported=count;runOnUiThread(()->{toast(imported+" de "+uris.size()+" canciones importadas");navigate("library");});});}else if(code==101&&data.getData()!=null){Uri uri=data.getData();io.execute(()->{try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Archivo vacío");List<Track> tracks=SpotdlImport.parse(new String(readBounded(in,10*1024*1024),StandardCharsets.UTF_8));long id=store.createPlaylist("Importada de spotDL");for(Track t:tracks)store.add(id,t);runOnUiThread(()->{toast(tracks.size()+" metadatos importados. Tocá una canción para buscar audio disponible.");navigate("library");});}catch(Exception e){runOnUiThread(()->toast("No se pudo importar: "+e.getMessage()));}});}}
    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);if(intent.getData()!=null)social.open(intent.getData().toString());}
    private void savePlaylistCover(Uri uri){long id=coverTarget;coverTarget=-1;if(id<0)return;toast("Preparando portada…");io.execute(()->{try{byte[] bytes;try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Imagen vacía");bytes=readBounded(in,15*1024*1024);}BitmapFactory.Options opts=new BitmapFactory.Options();opts.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,opts);if(opts.outWidth<=0||opts.outHeight<=0)throw new IOException("Imagen no compatible");opts.inSampleSize=1;while(opts.outWidth/opts.inSampleSize>1024||opts.outHeight/opts.inSampleSize>1024)opts.inSampleSize*=2;opts.inJustDecodeBounds=false;Bitmap bmp=BitmapFactory.decodeByteArray(bytes,0,bytes.length,opts);if(bmp==null)throw new IOException("No se pudo leer la imagen");int orientation=1;try{android.media.ExifInterface exif=new android.media.ExifInterface(new ByteArrayInputStream(bytes));orientation=exif.getAttributeInt(android.media.ExifInterface.TAG_ORIENTATION,1);}catch(IOException ignored){}Matrix transform=new Matrix();if(orientation==3)transform.setRotate(180);else if(orientation==6)transform.setRotate(90);else if(orientation==8)transform.setRotate(270);else if(orientation==2)transform.setScale(-1,1);else if(orientation==4)transform.setScale(1,-1);else if(orientation==5){transform.setRotate(90);transform.postScale(-1,1);}else if(orientation==7){transform.setRotate(270);transform.postScale(-1,1);}if(!transform.isIdentity()){Bitmap rotated=Bitmap.createBitmap(bmp,0,0,bmp.getWidth(),bmp.getHeight(),transform,true);if(rotated!=bmp){bmp.recycle();bmp=rotated;}}File file=new File(getFilesDir(),"playlist-"+id+"-"+System.currentTimeMillis()+".jpg");try(FileOutputStream out=new FileOutputStream(file)){if(!bmp.compress(Bitmap.CompressFormat.JPEG,88,out))throw new IOException("No se pudo guardar la imagen");}finally{bmp.recycle();}store.playlistField(id,"cover",Uri.fromFile(file).toString());runOnUiThread(()->{if(destroyed)return;String name=store.playlists().get(id);if(name!=null)showSaved(name,store.playlist(id),id);});}catch(Exception e){runOnUiThread(()->toast("No se pudo elegir la portada: "+e.getMessage()));}});}
    private void profileFile(boolean export){try{Intent intent=new Intent(export?Intent.ACTION_CREATE_DOCUMENT:Intent.ACTION_OPEN_DOCUMENT).setType(export?"application/json":"*/*").addCategory(Intent.CATEGORY_OPENABLE);if(export)intent.putExtra(Intent.EXTRA_TITLE,"Open-Music-profile.json");startActivityForResult(intent,export?106:107);}catch(ActivityNotFoundException e){toast("No hay selector de archivos disponible");}}
    private void handleProfileFile(int code,Uri uri){io.execute(()->{try{if(code==106){ProfileShare.Snapshot snapshot=ProfileShare.snapshot(social.profile,store);if(exportProfilePhotos){snapshot.portrait=ProfileImages.export(this,social.profile.image(false));snapshot.banner=ProfileImages.export(this,social.profile.image(true));}String json=ProfileShare.json(snapshot);if(json.length()>2*1024*1024)throw new IOException("El perfil supera el límite de 2 MB; exportá la biblioteca desde Ajustes");try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("No se pudo abrir el archivo");out.write(json.getBytes(StandardCharsets.UTF_8));}runOnUiThread(()->toast("Perfil completo exportado, sin audio ni archivos privados"));}else{String json;try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Archivo vacío");json=new String(readBounded(in,2*1024*1024),StandardCharsets.UTF_8);}social.open(json);}}catch(Exception e){runOnUiThread(()->toast("No se pudo abrir o guardar el perfil: "+e.getMessage()));}});}
    private Track localTrack(Uri uri)throws Exception{Track t=new Track();t.provider="local";t.id=uri.toString();t.local=uri.toString();t.title="Archivo de audio";t.artist="Artista desconocido";try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())t.title=c.getString(0);}MediaMetadataRetriever m=new MediaMetadataRetriever();try{m.setDataSource(this,uri);String title=m.extractMetadata(MediaMetadataRetriever.METADATA_KEY_TITLE),artist=m.extractMetadata(MediaMetadataRetriever.METADATA_KEY_ARTIST),album=m.extractMetadata(MediaMetadataRetriever.METADATA_KEY_ALBUM),duration=m.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION);if(title!=null)t.title=title;if(artist!=null)t.artist=artist;if(album!=null)t.album=album;if(duration!=null)t.duration=(int)(Long.parseLong(duration)/1000);byte[] art=m.getEmbeddedPicture();if(art!=null&&art.length<10*1024*1024){File f=new File(getFilesDir(),Integer.toHexString(t.key().hashCode())+".cover");try(FileOutputStream out=new FileOutputStream(f)){out.write(art);}t.artwork=Uri.fromFile(f).toString();}}finally{m.release();}return t;}
    private static byte[] readBounded(InputStream in,int max)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>max)throw new IOException("El archivo supera el tamaño permitido");out.write(buffer,0,n);}return out.toByteArray();}
